import "server-only";

// US ZIP centroids from the GeoNames postal-code dataset (CC BY 4.0,
// https://download.geonames.org/export/zip/). Server-only: this never reaches
// the browser bundle.
//
// Fixed-width records of 16 chars, sorted by ZIP so lookups can binary-search
// without building a Map: ZIP(5) + round(lat*1000)(5) + round(lng*1000)+180000(6).
export const ZIP_RECORD_LEN = 16;
export const ZIP_COUNT = 41465;

export const ZIP_DATA =
  "";

// Two-letter state per record, in the same order as ZIP_DATA.
export const ZIP_STATES =
  "";
